@contextmanager
def _chrome_page(url, debug_port):
    """Yield a page with a true 390x1200 CSS viewport set before navigation."""

    chrome = _find_chrome()
    assert chrome, "Chrome is required for the render gate"
    with tempfile.TemporaryDirectory(prefix="tiny-llm-render-") as profile:
        proc = subprocess.Popen(
            [
                chrome,
                "--headless=new",
                "--disable-gpu",
                f"--remote-debugging-port={debug_port}",
                "--remote-allow-origins=*",
                "--force-dark-mode",
                "--window-size=390,1200",
                f"--user-data-dir={profile}",
                "about:blank",
            ],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
        ws = None
        try:
            target = _wait_for_debug_target(debug_port)
            ws = websocket.create_connection(target["webSocketDebuggerUrl"], timeout=10)
            client = _CDPClient(ws)
            client.command("Page.enable")
            client.command(
                "Emulation.setDeviceMetricsOverride",
                {
                    "width": CSS_VIEWPORT_WIDTH,
                    "height": CSS_VIEWPORT_HEIGHT,
                    "deviceScaleFactor": 1,
                    # Mobile device emulation uses overlay scrollbars, so the
                    # 390 CSS-pixel device viewport remains 390 on Linux and
                    # macOS instead of losing 15px to a desktop scrollbar.
                    "mobile": True,
                    "screenWidth": CSS_VIEWPORT_WIDTH,
                    "screenHeight": CSS_VIEWPORT_HEIGHT,
                },
            )
            client.command("Page.navigate", {"url": url})
            deadline = time.monotonic() + 15
            while time.monotonic() < deadline:
                if client.evaluate("document.readyState") == "complete":
                    break
                time.sleep(0.2)
            else:
                raise AssertionError(f"page did not finish navigating: {url}")
            time.sleep(0.5)
            yield client
        finally:
            if ws is not None:
                ws.close()
            proc.terminate()
            proc.wait(timeout=5)


_RENDER_AUDIT = r"""(() => {
    const vw = visualViewport.width;
    const tolerance = 1;
    const content = document.querySelector('.content');
    const contentRect = content ? content.getBoundingClientRect() : null;
    const containers = new Set();
    const containerInfo = new Map();
    const containerProblems = [];

    for (const el of document.querySelectorAll('main *')) {
        const cs = getComputedStyle(el);
        const overflowEnabled = cs.overflowX === 'auto' || cs.overflowX === 'scroll';
        const explicit =
            (el.classList && el.classList.contains('table-wrapper')) ||
            el.tagName === 'PRE' || el.tagName === 'CODE';
        if (!explicit || !overflowEnabled) continue;
        containers.add(el);
        const rect = el.getBoundingClientRect();
        const hasOverflow = el.scrollWidth > el.clientWidth + tolerance;
        const scrollbarVisible = cs.scrollbarWidth !== 'none';
        const affordanceVisible = hasOverflow && overflowEnabled && scrollbarVisible;
        const info = {
            tag: el.tagName,
            cls: (el.className || '').toString().slice(0, 30),
            left: rect.left,
            right: rect.right,
            clientWidth: el.clientWidth,
            scrollWidth: el.scrollWidth,
            hasOverflow,
            affordanceVisible,
        };
        containerInfo.set(el, info);
        if (rect.left < -tolerance || rect.right > vw + tolerance ||
            (hasOverflow && !affordanceVisible)) {
            containerProblems.push({
                ...info,
                left: Math.round(rect.left),
                right: Math.round(rect.right),
            });
        }
    }

    const nearestContainer = (el) => {
        let node = el.parentElement;
        while (node) {
            if (containers.has(node)) return node;
            node = node.parentElement;
        }
        return null;
    };

    const clipped = [];
    let checkedCount = 0;
    let worstVisibleLeft = vw;
    let worstVisibleRight = 0;
    for (const el of document.querySelectorAll(
        'main h1, main h2, main h3, main h4, main h5, main h6, ' +
        'main p, main li, main pre, main code, main td, main th'
    )) {
        if (containers.has(el)) continue;
        const rect = el.getBoundingClientRect();
        const cs = getComputedStyle(el);
        if (rect.width <= 0 || rect.height <= 0 || cs.visibility === 'hidden' ||
            cs.display === 'none') continue;
        checkedCount += 1;
        const withinViewport =
            rect.left >= -tolerance && rect.right <= vw + tolerance;
        const container = nearestContainer(el);
        const info = container ? containerInfo.get(container) : null;
        const safelyScrollable = Boolean(
            info && info.left >= -tolerance && info.right <= vw + tolerance &&
            info.affordanceVisible
        );
        if (withinViewport) {
            worstVisibleLeft = Math.min(worstVisibleLeft, rect.left);
            worstVisibleRight = Math.max(worstVisibleRight, rect.right);
        } else if (!safelyScrollable) {
            clipped.push({
                tag: el.tagName,
                left: Math.round(rect.left),
                right: Math.round(rect.right),
                text: (el.textContent || '').slice(0, 60).replace(/\s+/g, ' '),
            });
        }
    }

    return {
        innerWidth,
        visualViewportWidth: visualViewport.width,
        bodyScroll: document.body.scrollWidth,
        docScroll: document.documentElement.scrollWidth,
        contentLeft: contentRect ? Math.round(contentRect.left) : null,
        contentRight: contentRect ? Math.round(contentRect.right) : null,
        checkedCount,
        clippedCount: clipped.length,
        clipped: clipped.slice(0, 12),
        containerProblems,
        worstVisibleLeft: Math.round(worstVisibleLeft),
        worstVisibleRight: Math.round(worstVisibleRight),
    };
})()"""


def _png_dimensions(data):
    assert data.startswith(b"\x89PNG\r\n\x1a\n"), "Chrome did not return a PNG"
    return struct.unpack(">II", data[16:24])


def _assert_render_visible(client, page):
    """Run the production render guard and return its measurements + PNG."""

    audit = client.evaluate(_RENDER_AUDIT)
    screenshot = client.command(
        "Page.captureScreenshot", {"format": "png", "fromSurface": True}
    )
    png = base64.b64decode(screenshot["result"]["data"])
    png_width, png_height = _png_dimensions(png)

    assert audit["innerWidth"] == CSS_VIEWPORT_WIDTH, (
        f"{page}: innerWidth {audit['innerWidth']} is not 390 CSS px"
    )
    assert audit["visualViewportWidth"] == CSS_VIEWPORT_WIDTH, (
        f"{page}: visualViewport.width {audit['visualViewportWidth']} is not 390"
    )
    assert png_width == CSS_VIEWPORT_WIDTH, (
        f"{page}: screenshot width {png_width} is not 390px"
    )
    assert png_height == CSS_VIEWPORT_HEIGHT, (
        f"{page}: screenshot height {png_height} is not 1200px"
    )
    assert audit["bodyScroll"] <= CSS_VIEWPORT_WIDTH + 1, (
        f"{page}: page overflow (body {audit['bodyScroll']} vs 390)"
    )
    assert audit["docScroll"] <= CSS_VIEWPORT_WIDTH + 1, (
        f"{page}: document overflow (doc {audit['docScroll']} vs 390)"
    )
    if audit["contentLeft"] is not None:
        assert audit["contentLeft"] >= -1, (
            f"{page}: content starts off-screen left ({audit['contentLeft']})"
        )
        assert audit["contentRight"] <= CSS_VIEWPORT_WIDTH + 1, (
            f"{page}: content extends past 390px ({audit['contentRight']})"
        )
    assert audit["checkedCount"] > 0, f"{page}: no rendered content was checked"
    assert audit["clippedCount"] == 0, (
        f"{page}: visible content is clipped: {audit['clipped']}"
    )
    assert audit["containerProblems"] == [], (
        f"{page}: invalid scroll container: {audit['containerProblems']}"
    )
    return audit, png


@pytest.mark.parametrize("page", PAGES)
def test_narrow_dark_render_is_fully_visible(serve, page):
    with _chrome_page(f"{serve}/{page}", 9247) as client:
        audit, png = _assert_render_visible(client, page)
    assert audit["visualViewportWidth"] == 390
    assert _png_dimensions(png)[0] == 390


def test_render_gate_catches_bare_overflowing_table(serve):
    """A real 600px bare table must fail the same production render guard."""

    page = "week4-01-agent-loop.html"
    with _chrome_page(f"{serve}/{page}", 9249) as client:
        client.evaluate(
            """(() => {
                const table = document.createElement('table');
                table.style.tableLayout = 'fixed';
                table.style.width = '600px';
                table.style.maxWidth = 'none';
                const row = document.createElement('tr');
                for (const text of ['File', 'Function or type', 'Responsibility']) {
                    const cell = document.createElement('th');
                    cell.textContent = text;
                    row.appendChild(cell);
                }
                table.appendChild(row);
                document.querySelector('main').appendChild(table);
                return true;
            })()"""
        )
        with pytest.raises(AssertionError):
            _assert_render_visible(client, page)
